# Extract regions based on separators
def extract_regions(input_grid):
    H, W = len(input_grid), len(input_grid[0])

    sep_cols = set()
    for c in range(W):
        if all(input_grid[r][c] == 7 for r in range(H)):
            sep_cols.add(c)

    sep_rows = set()
    for r in range(H):
        if all(input_grid[r][c] == 7 for c in range(W)):
            sep_rows.add(r)

    # Build strips
    rows = []
    start = 0
    for s in sep_rows:
        rows.append((start, s-1))  # inclusive
        start = s + 1
    rows.append((start, H-1))

    cols = []
    start = 0
    for s in sep_cols:
        cols.append((start, s-1))
        start = s + 1
    cols.append((start, W-1))

    # Extract regions
    regions = []
    for ri, (r1, r2) in enumerate(rows):
        for ci, (c1, c2) in enumerate(cols):
            # Collect all values in region
            values = []
            for r in range(r1, r2+1):
                for c in range(c1, c2+1):
                    values.append(input_grid[r][c])
            # Count occurrences of each value
            counts = {}
            for v in values:
                counts[v] = counts.get(v, 0) + 1
            regions.append(values)

    return rows, cols, regions, len(rows), len(cols)

# Test with demo input
