rows, cols, regions, R, C = extract_regions(input_grid)

print(f"Grid: {R}x{C} regions")
print(f"Row strips: {[(r[0]-r[1]+1, r[0], r[1]) for r in rows]}")
print(f"Col strips: {[(c[0]-c[1]+1, c[0], c[1]) for c in cols]}")

print("\nFirst 5 regions (all values):")
for i, reg in enumerate(regions[:5]):
    print(f"Region ({i//C},{i%C}): {reg}")

# Find what makes a region output 1
print("\n\nChecking for value 6 in regions with output 1:")
for ri in range(R):
    for ci in range(C):
        idx = ri * C + ci
        val6 = regions[idx].count(6)
        print(f"Region ({ci},{ri}): count(6)={val6}")

